receipts=[]
for rel,mapping in translations.items():
 p=R/'source'/rel;s=p.read_text()
 for a,b in mapping.items():
  count=s.count(a)
  if count:s=s.replace(a,b);receipts.append({'path':rel,'old':a,'new':b,'count':count})
 p.write_text(s)
(R/'data-intercept-evidence/translations.json').write_text(json.dumps(receipts,ensure_ascii=False,indent=2))
print('Applied',len(receipts),'exact phrase translations')
